    <file>services/geminiService.ts</file>
    <description>Improved error handling for missing/invalid API keys on production environments and prevented module-level crashes.</description>
    <content><![CDATA[
import { GoogleGenAI, Type } from "@google/genai";
import type { LessonPlan, Idea, IdeaSection, AgeGroup, ChatMessage } from '../types';

// Safely initialize the client.
// We do NOT throw an error at the top level to prevent the entire app from crashing on load.
// Instead, we check for the key inside each function.
const apiKey = process.env.API_KEY;
const ai = apiKey ? new GoogleGenAI({ apiKey: apiKey }) : null;

// --- Retry Logic Helper ---
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function generateWithRetry(model: string, params: any, retries = 3, delay = 2000): Promise<any> {
    if (!ai) {
        throw new Error("مفتاح API غير موجود. يرجى إضافته (API_KEY) في إعدادات Vercel ثم إعادة النشر (Redeploy).");
    }

    try {
        // Construct the call parameters correctly for the SDK
        const callParams = { model, ...params };
        return await ai.models.generateContent(callParams);
    } catch (error: any) {
        const status = error.status || error.response?.status;
        const message = error.message || '';

        // Handle specific API Key errors (400 Bad Request often means invalid key format, 403 means permission denied)
        if (status === 400 && message.includes('API key')) {
            throw new Error("مفتاح API غير صالح. تأكد من صحة المفتاح في إعدادات Vercel.");
        }
        if (status === 403) {
            throw new Error("تم رفض الوصول. قد يكون مفتاح API محظوراً أو غير مفعل.");
        }

        // Check for Rate Limit (429) or Service Unavailable (503) or generic Network errors
        const isRateLimit = status === 429;
        const isServerBusy = status === 503;
        const isNetworkError = message.includes('fetch failed') || message.includes('network');

        if (retries > 0 && (isRateLimit || isServerBusy || isNetworkError)) {
            console.warn(`Gemini API Error (${status || 'Network'}). Retrying in ${delay}ms...`);
            await sleep(delay);
            // Exponential backoff: double the delay for the next retry
            return generateWithRetry(model, params, retries - 1, delay * 2);
        }

        // If we ran out of retries or it's a non-retriable error
        if (isRateLimit) {
            throw new Error("عفواً، الخدمة مشغولة جداً حالياً (Rate Limit). انتظر دقيقة وحاول مرة أخرى.");
        }

        throw error;
    }
}

