import { GoogleGenAI, Type } from "@google/genai";
import type { LessonPlan, Idea, IdeaSection, AgeGroup, ChatMessage } from '../types';

// Safely initialize the client.
// We do NOT throw an error at the top level to prevent the entire app from crashing on load.
// Instead, we check for the key inside each function.
const apiKey = process.env.API_KEY;
const ai = apiKey ? new GoogleGenAI({ apiKey: apiKey }) : null;

// --- Retry Logic Helper ---
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function generateWithRetry(model: string, params: any, retries = 5, delay = 1000): Promise<any> {
    if (!ai) {
        throw new Error("مفتاح API غير موجود. يرجى إضافته (API_KEY) في إعدادات Vercel ثم إعادة النشر (Redeploy).");
    }

    try {
        // Construct the call parameters correctly for the SDK
        const callParams = { model, ...params };
        return await ai.models.generateContent(callParams);
    } catch (error: any) {
        const status = error.status || error.response?.status;
        const message = error.message || '';

        // Handle specific API Key errors (Permanent errors - No Retry)
        if (status === 400 && message.includes('API key')) {
            throw new Error("مفتاح API غير صالح. تأكد من صحة المفتاح.");
        }
        if (status === 403) {
            throw new Error("تم رفض الوصول. (403 Forbidden). تأكد أن المفتاح مفعل وأنك في دولة تدعم الخدمة.");
        }

        // Retryable Errors:
        // 429: Rate Limit (Too many requests)
        // 503: Service Unavailable (Server Overloaded - Very Common)
        // 500: Internal Server Error
        // Network errors (fetch failed)
        const isRateLimit = status === 429;
        const isServerOverloaded = status === 503;
        const isInternalError = status >= 500;
        const isNetworkError = message.includes('fetch failed') || message.includes('network') || message.includes('Load failed');

        if (retries > 0 && (isRateLimit || isServerOverloaded || isInternalError || isNetworkError)) {
            // Determine wait time. If it's a rate limit or overload, wait longer.
            const waitTime = (isRateLimit || isServerOverloaded) ? delay * 2 : delay;

            console.warn(`Gemini API Warning: ${status || 'Network Error'}. Retrying in ${waitTime}ms... (Attempts left: ${retries})`);
            await sleep(waitTime);

            // Exponential backoff: double the delay for the next retry
            return generateWithRetry(model, params, retries - 1, waitTime);
        }

        // Final Error Handling after retries are exhausted
        if (isRateLimit) {
            throw new Error("عفواً، لقد تجاوزنا الحد المسموح من الطلبات (Rate Limit). يرجى الانتظار دقيقة والمحاولة مرة أخرى.");
        }
        if (isServerOverloaded) {
            throw new Error("سيرفرات جوجل مشغولة حالياً (Overloaded). الخدمة تواجه ضغطاً عالياً، حاول مرة أخرى.");
        }
        if (isNetworkError) {
            throw new Error("مشكلة في الاتصال بالإنترنت. يرجى التحقق من الشبكة.");
        }

        throw error;
    }
}

